// D7 local versus chronological robustness (PROTOCOL.md §6): each fold primary's own sealed SELECTION neighbourhood
// (2 × 128 draws, the family that ranked it), regenerated by its study's own `drawsOf(cfg, o, famOf('select',
// ['select', rep, cutoff], 'joint'))` (seeds, radii and clipping unchanged), de-duplicated as the study pooled it, and
// replayed once on the fold's evaluation door with boundaries [cutoff end]. Parity: the regenerated draws' training nets
// (the boundary equity of the continuous run = the training-door net, causal) must reproduce the sealed selection
// median, p10 and robust net to the cent. Then: how many of these training-qualified neighbours breach $35,000 on the
// slice. Report-only; nothing is selected.
// Run from the repository root with WFD_SES_WT=<session worktree> (the session study's code at 18674b39).
import path from 'node:path';
import { openPrefixDoor } from '../../src/vg-d1-growth-joint/data.ts';
import { evaluate as p3Evaluate } from '../../src/vg-d1-growth-joint/evaluate.ts';
import { drawsOf as drawsOf5B, famOf as famOf5B } from '../../src/vg-lifecycle-matched-optimization/qualify.ts';
import { optionsOfInc as options5B } from '../../src/vg-lifecycle-matched-optimization/config.ts';
import { drawsOf as drawsOfSh, famOf as famOfSh } from '../../src/vg-l0-shadow-eligibility/qualify.ts';
import { optionsOfInc as optionsSh } from '../../src/vg-l0-shadow-eligibility/config.ts';
import { evaluate as shEvaluate } from '../../src/vg-l0-shadow-eligibility/evaluate.ts';
import { audited, ceiling, folds, logDoor, r2, readRecord, repoRoot, resultsDir, sealJson } from './common.ts';

const wt = process.env.WFD_SES_WT;

if (!wt) throw new Error('WFD_SES_WT (the session study worktree) is required');

const imp = async <T>(rel: string) => (await import(path.join(wt, rel))) as T;
const sesData = await imp<{ openPrefixDoor: (d: string, p: string, q: boolean) => Promise<any> }>('src/vg-d1-growth-joint/data.ts');
const sesQ = await imp<{ drawsOf: (...a: any[]) => any[]; famOf: (...a: any[]) => any }>('src/vg-l0-session-hold/qualify.ts');
const sesUnit = await imp<{ evaluateUnit: (...a: any[]) => any }>('src/vg-l0-session-hold/unit.ts');
const sesConfig = await imp<{ optionsOfInc: (inc: string) => any }>('src/vg-l0-session-hold/config.ts');

const quantile = (x: number[], p: number) => {
  const s = [...x].sort((a, b) => a - b);
  const h = (s.length - 1) * p;
  const lo = Math.floor(h);

  return s[lo]! + (s[Math.ceil(h)]! - s[lo]!) * (h - lo);
};
const wilson = (k: number, n: number) => {
  const z = 1.959964;
  const p = k / n;
  const d = 1 + (z * z) / n;
  const c = p + (z * z) / (2 * n);
  const h = z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n));

  return [r2((100 * (c - h)) / d) / 100, r2((100 * (c + h)) / d) / 100];
};

const doorCache = new Map<string, any>();
const doorOf = async (kind: 'main' | 'ses', name: string) => {
  const k = `${kind}|${name}`;

  if (!doorCache.has(k)) {
    const d = kind === 'main' ? await openPrefixDoor(name as never, 'wfd D7', true) : await sesData.openPrefixDoor(name, 'wfd D7', true);

    logDoor(name, `D7 selection-neighbourhood replay (${kind === 'main' ? 'this checkout' : 'session worktree 18674b39'}; development door)`, {
      GDX: d.sym.GDX.dataSha256,
      VGT: d.sym.VGT.dataSha256
    });
    doorCache.set(k, d);
  }
  return doorCache.get(k);
};

let simulations = 0;
const out: Record<string, unknown>[] = [];

for (const key of ['5B-L0', 'SES', 'B1', 'B2'] as const) {
  for (const f of folds) {
    if (process.env.WFD_ONLY && process.env.WFD_ONLY !== `${key}:${f.fold}`) continue; // a check of one subject (dry runs only)

    const a = audited[key];
    const ev = readRecord<{ primary: Record<string, string>; rows: { label: string; mode?: string; unit?: string; cfg: any; sliceNet: number; sliceDd: number }[] }>(
      path.join(repoRoot, a.path, 'results/folds', f.fold, 'evaluation.json')
    );
    const label = key === '5B-L0' ? ev.primary.L0! : key === 'SES' ? ev.primary.ses! : ev.primary[key]!;
    const row = ev.rows.find((r) => r.label === label && (key === '5B-L0' ? r.mode === 'L0' : key === 'SES' ? r.unit === 'ses' : true))!;
    const selFile =
      key === 'B1' || key === 'B2'
        ? path.join(a.path, 'results/folds', f.fold, key === 'B1' ? 'B1' : 'B2-g', 'selection.json')
        : path.join(a.path, 'results/folds', f.fold, 'selection.json');
    const evidence = readRecord<{ evidence: { label: string; select: Record<string, number>; centre: { net: number; dd: number } }[] }>(path.join(repoRoot, selFile)).evidence.find(
      (e) => e.label === label
    )!;
    const cfg = row.cfg;
    const base = key === '5B-L0' ? options5B(cfg.inc) : key === 'SES' ? sesConfig.optionsOfInc(cfg.inc) : optionsSh(cfg.inc);
    const fams = [1, 2].map((rep) =>
      key === '5B-L0'
        ? drawsOf5B(cfg, base, famOf5B('select', ['select', rep, f.fold], 'joint'))
        : key === 'SES'
          ? sesQ.drawsOf(cfg, base, sesQ.famOf('select', ['select', rep, f.fold], 'joint'))
          : drawsOfSh(cfg, base, famOfSh('select', ['select', rep, f.fold], 'joint'))
    );
    const seen = new Set<string>();
    const draws: { quad: any; clipped: number; id: string }[] = [];

    for (const fam of fams) for (const d of fam) if (!seen.has(d.id)) (seen.add(d.id), draws.push(d));

    const door = await doorOf(key === 'SES' ? 'ses' : 'main', f.evalDoor);
    const o = { ...base, boundaries: [f.boundary] };
    const recs = draws.map((d) => {
      simulations++;

      const r =
        key === '5B-L0' ? p3Evaluate(door, d.quad, o) : key === 'SES' ? sesUnit.evaluateUnit(door, d.quad, o, 'ses') : shEvaluate(door, d.quad, o, cfg.sh);

      return { train: r.periods[0].equity as number, sliceNet: r.periods[0].after as number, sliceDd: r.periods[0].dd as number, wholeDd: r.dd as number, lots: r.lots as number };
    });
    const tn = recs.map((r) => r.train);
    const median = r2(quantile(tn, 0.5));
    const p10 = r2(quantile(tn, 0.1));
    const robust = r2(0.5 * quantile(tn, 0.5) + 0.5 * quantile(tn, 0.1));
    const sd = recs.map((r) => r.sliceDd);
    const breaches = sd.filter((x) => x > ceiling).length;
    const parity = median === evidence.select.median && p10 === evidence.select.p10 && robust === evidence.select.robust;

    out.push({
      path: key,
      fold: f.fold,
      label,
      draws: draws.length,
      parity: { ok: parity, median, sealedMedian: evidence.select.median, p10, sealedP10: evidence.select.p10, robust, sealedRobust: evidence.select.robust },
      training: {
        centreNet: evidence.centre.net,
        centreDd: evidence.centre.dd,
        selectP90Dd: evidence.select.p90Dd,
        selectBreachShare: evidence.select.breachShare,
        selectWorstDd: evidence.select.worstDd
      },
      slice: {
        centreNet: row.sliceNet,
        centreDd: row.sliceDd,
        medianNet: r2(quantile(recs.map((r) => r.sliceNet), 0.5)),
        p10Net: r2(quantile(recs.map((r) => r.sliceNet), 0.1)),
        p90Net: r2(quantile(recs.map((r) => r.sliceNet), 0.9)),
        losingShare: r2((100 * recs.filter((r) => r.sliceNet <= 0).length) / recs.length) / 100,
        medianDd: r2(quantile(sd, 0.5)),
        p10Dd: r2(quantile(sd, 0.1)),
        p90Dd: r2(quantile(sd, 0.9)),
        minDd: r2(Math.min(...sd)),
        maxDd: r2(Math.max(...sd)),
        breaches,
        breachShare: r2((100 * breaches) / sd.length) / 100,
        breachInterval: wilson(breaches, sd.length),
        acceptable: recs.filter((r) => r.sliceNet > 0 && r.sliceDd <= ceiling).length
      }
    });
    console.log(
      `${key} ${f.fold} ${label}: ${draws.length} draws; parity ${parity ? 'ok' : `DIFF (median ${median} vs ${evidence.select.median}, p10 ${p10} vs ${evidence.select.p10})`}; slice breaches ${breaches}/${sd.length} (training select breach share ${evidence.select.breachShare}); median slice DD ${r2(quantile(sd, 0.5))}`
    );
  }
}

if (process.env.WFD_ONLY && !process.argv.includes('--dry')) throw new Error('WFD_ONLY is for dry runs only');

sealJson(
  path.join(resultsDir, 'neighbours', 'selection-neighbourhoods.json'),
  {
    stage: 'D7 fold primaries’ selection neighbourhoods replayed on their slices (report-only)',
    simulations,
    parityFailed: out.filter((x) => !(x.parity as { ok: boolean }).ok).length,
    subjects: out,
    finished: new Date().toISOString()
  },
  'D7 neighbourhoods'
);
console.log(`simulations ${simulations}`);
